import{_ as t,c as a,o as r,a3 as i}from"./chunks/framework.MI-M1z4O.js";const p=JSON.parse('{"title":"Daily Scrum","description":"Step-by-step guide to running an effective Daily Scrum. Learn the core principles and practical tips for a 15-minute meeting that strengthens agile team collaboration, tracks progress, and resolves blockers.","frontmatter":{"title":"Daily Scrum","description":"Step-by-step guide to running an effective Daily Scrum. Learn the core principles and practical tips for a 15-minute meeting that strengthens agile team collaboration, tracks progress, and resolves blockers.","head":[["meta",{"name":"keywords","content":"Daily Scrum, scrum meeting, agile, agile methodology, Scrum Master, team collaboration, daily standup, how to run a scrum, agile coaching, resolving team blockers"}],["meta",{"property":"og:title","content":"Daily Scrum"}],["meta",{"property":"og:description","content":"Step-by-step guide to running an effective Daily Scrum. Learn the core principles and practical tips for a 15-minute meeting that strengthens agile team collaboration, tracks progress, and resolves blockers."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/agile/dailyScrum"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/dailyScrum"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/dailyScrum"}]],"sort":3000},"headers":[],"relativePath":"en/agile/dailyScrum.md","filePath":"en/agile/dailyScrum.md","lastUpdated":1795293539000}'),o={name:"en/agile/dailyScrum.md"};function n(l,e,s,d,c,m){return r(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="how-to-run-a-daily-scrum" tabindex="-1">How to Run a Daily Scrum <a class="header-anchor" href="#how-to-run-a-daily-scrum" aria-label="Permalink to “How to Run a Daily Scrum”">​</a></h1><ol><li><strong>Fixed Time &amp; Place</strong></li></ol><ul><li>Same time every day (e.g., 9:00 AM)</li><li>Same place (meeting room or online video call)</li></ul><ol start="2"><li><strong>Participants</strong></li></ol><ul><li>Entire development team (developers, QA, etc.)</li><li>Scrum Master (facilitator); Product Owner (PO) may attend as an observer</li></ul><ol start="3"><li><strong>Format</strong></li></ol><ul><li><p>Timeboxed to <strong>15 minutes or less</strong></p></li><li><p>Team members <strong>take turns sharing</strong></p></li><li><p>Answer <strong>3 core questions</strong> briefly:</p><ol><li>What did you do yesterday?</li><li>What will you do today?</li><li>Are there any blockers impeding your progress?</li></ol></li></ul><ol start="4"><li><strong>Core Principles</strong></li></ol><ul><li>Focus on <strong>high-level alignment</strong> rather than deep technical explanations</li><li>Discuss blockers separately after the Scrum ends</li><li>Aim for <strong>team synchronization</strong>, not status reporting</li></ul><hr><h1 id="daily-scrum-sample-script" tabindex="-1">Daily Scrum Sample Script <a class="header-anchor" href="#daily-scrum-sample-script" aria-label="Permalink to “Daily Scrum Sample Script”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><ul><li><strong>Time</strong>: Every morning at 10:00 AM (15 minutes max)</li><li><strong>Attendees</strong>: Entire development team, Scrum Master, and Product Owner (PO) if needed</li><li><strong>Format</strong>: Standing meeting (video call for remote teams)</li></ul><hr><h2 id="_1-opening-purpose-alignment-2-min" tabindex="-1">1. Opening &amp; Purpose Alignment (2 min) <a class="header-anchor" href="#_1-opening-purpose-alignment-2-min" aria-label="Permalink to “1. Opening &amp; Purpose Alignment (2 min)”">​</a></h2><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Good morning, everyone. Let&#39;s start our Daily Scrum. Please share what you did yesterday, what you plan to work on today, and any blockers you&#39;re running into.&quot;</p></blockquote><hr><h2 id="_2-team-progress-updates-10-min" tabindex="-1">2. Team Progress Updates (10 min) <a class="header-anchor" href="#_2-team-progress-updates-10-min" aria-label="Permalink to “2. Team Progress Updates (10 min)”">​</a></h2><h3 id="alex-developer" tabindex="-1">Alex (Developer) <a class="header-anchor" href="#alex-developer" aria-label="Permalink to “Alex (Developer)”">​</a></h3><blockquote><p>&quot;Yesterday, I completed the user login API. Today, I&#39;m going to implement the user profile lookup feature. No blockers at the moment.&quot;</p></blockquote><h3 id="sam-designer" tabindex="-1">Sam (Designer) <a class="header-anchor" href="#sam-designer" aria-label="Permalink to “Sam (Designer)”">​</a></h3><blockquote><p>&quot;Yesterday, I finished the payment page UI design and handed it off to the development team. Today, I&#39;ll start designing the admin page. However, there are a few points I need to align on with the dev team—could we have a quick sync this afternoon?&quot;</p></blockquote><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Sure, I&#39;ll coordinate a time with the relevant team members right after this meeting.&quot;</p></blockquote><h3 id="jordan-backend" tabindex="-1">Jordan (Backend) <a class="header-anchor" href="#jordan-backend" aria-label="Permalink to “Jordan (Backend)”">​</a></h3><blockquote><p>&quot;Yesterday, I worked on database optimization, and today I&#39;ll run performance tests. However, CPU utilization on the test server looks high, so we may need to monitor it.&quot;</p></blockquote><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;I&#39;ll log that as a blocker and follow up with the infrastructure team after the meeting.&quot;</p></blockquote><h3 id="casey-qa" tabindex="-1">Casey (QA) <a class="header-anchor" href="#casey-qa" aria-label="Permalink to “Casey (QA)”">​</a></h3><blockquote><p>&quot;Yesterday, I finished testing the login feature, and today I&#39;ll start testing the newly added payment feature. There are a few test scenarios I need the dev team to confirm.&quot;</p></blockquote><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;I&#39;ll connect you with the developers involved as soon as we wrap up.&quot;</p></blockquote><hr><h2 id="_3-blocker-summary-action-plan-2-min" tabindex="-1">3. Blocker Summary &amp; Action Plan (2 min) <a class="header-anchor" href="#_3-blocker-summary-action-plan-2-min" aria-label="Permalink to “3. Blocker Summary &amp; Action Plan (2 min)”">​</a></h2><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;To recap the blockers shared today:</p><ol><li>Design–dev alignment meeting needed</li><li>High CPU utilization on the test server</li><li>QA test scenario confirmation needed</li></ol><p>I&#39;ll coordinate with the respective owners on these three items.&quot;</p></blockquote><hr><h2 id="_4-closing-1-min" tabindex="-1">4. Closing (1 min) <a class="header-anchor" href="#_4-closing-1-min" aria-label="Permalink to “4. Closing (1 min)”">​</a></h2><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Everyone is aligned on today&#39;s work and we&#39;ve captured all blockers. Let&#39;s wrap up here, and those who need to follow up can stay on for separate discussions. Have a great day!&quot;</p></blockquote><hr><h2 id="tips-for-running-an-effective-daily-scrum" tabindex="-1">Tips for Running an Effective Daily Scrum <a class="header-anchor" href="#tips-for-running-an-effective-daily-scrum" aria-label="Permalink to “Tips for Running an Effective Daily Scrum”">​</a></h2><ul><li><strong>Keep it timeboxed</strong>: Standing during the meeting is recommended to stay within the 15-minute limit</li><li><strong>No problem-solving during the standup</strong>: Schedule separate time for deep-dive discussions</li><li><strong>Encourage full participation</strong>: Foster an environment where every team member speaks evenly</li><li><strong>Use visual aids</strong>: Pair the standup with a Kanban board or task management tool</li><li><strong>Focus on blockers</strong>: Always establish concrete action plans to remove impediments</li></ul><hr><h2 id="sample-meeting-log" tabindex="-1">Sample Meeting Log <a class="header-anchor" href="#sample-meeting-log" aria-label="Permalink to “Sample Meeting Log”">​</a></h2><table tabindex="0"><thead><tr><th>Owner</th><th>Yesterday</th><th>Today</th><th>Blockers</th></tr></thead><tbody><tr><td>Alex (Developer)</td><td>Completed login API</td><td>Implement profile lookup</td><td>None</td></tr><tr><td>Sam (Designer)</td><td>Completed payment page UI</td><td>Start admin page design</td><td>Alignment needed with dev team</td></tr><tr><td>Jordan (Backend)</td><td>Database optimization</td><td>Run performance tests</td><td>High CPU utilization on test server</td></tr><tr><td>Casey (QA)</td><td>Completed login testing</td><td>Start payment feature testing</td><td>Test scenarios need confirmation</td></tr></tbody></table><hr><h1 id="daily-scrum-facilitation-checklist" tabindex="-1">Daily Scrum Facilitation Checklist <a class="header-anchor" href="#daily-scrum-facilitation-checklist" aria-label="Permalink to “Daily Scrum Facilitation Checklist”">​</a></h1><h2 id="facilitator-scrum-master-checklist" tabindex="-1">Facilitator (Scrum Master) Checklist <a class="header-anchor" href="#facilitator-scrum-master-checklist" aria-label="Permalink to “Facilitator (Scrum Master) Checklist”">​</a></h2><ul><li>[ ] Did the meeting start at the same time and place (or online link) every day?</li><li>[ ] Are you prepared to wrap up within 15 minutes?</li><li>[ ] Did you guide each team member to share only <strong>Yesterday / Today / Blockers</strong>?</li><li>[ ] Were all reported <strong>blocking issues</strong> recorded for separate follow-up?</li><li>[ ] After the Scrum, did you pull in only the people needed for follow-up issue resolution?</li></ul><hr><h2 id="team-member-sharing-checklist" tabindex="-1">Team Member Sharing Checklist <a class="header-anchor" href="#team-member-sharing-checklist" aria-label="Permalink to “Team Member Sharing Checklist”">​</a></h2><ul><li>[ ] What did I complete yesterday?</li><li>[ ] What will I work on today?</li><li>[ ] Is anything blocking my progress?</li></ul><p>Keep updates <strong>brief and clear (1–2 sentences)</strong>. Save problem-solving discussions for after the Scrum.</p><hr><h2 id="team-member-update-template" tabindex="-1">Team Member Update Template <a class="header-anchor" href="#team-member-update-template" aria-label="Permalink to “Team Member Update Template”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Name]</span></span>
<span class="line"><span>- Yesterday:</span></span>
<span class="line"><span>- Today:</span></span>
<span class="line"><span>- Blockers:</span></span></code></pre></div><hr><h2 id="team-scrum-board-example-whiteboard-online-tool" tabindex="-1">Team Scrum Board Example (Whiteboard / Online Tool) <a class="header-anchor" href="#team-scrum-board-example-whiteboard-online-tool" aria-label="Permalink to “Team Scrum Board Example (Whiteboard / Online Tool)”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Yesterday</th><th>Today</th><th>Blockers (Blocking Issues)</th></tr></thead><tbody><tr><td>Chris</td><td>Completed login API refactoring</td><td>Start Google social login integration</td><td>No access to Google OAuth docs</td></tr><tr><td>Jamie</td><td>Wrote and partially executed signup test cases</td><td>Complete signup test suite and file bug reports</td><td>Test server disconnecting frequently</td></tr><tr><td>Morgan</td><td>Worked on dashboard UI</td><td>Integrate chart library and connect APIs</td><td>Latest API spec not yet shared</td></tr></tbody></table><hr><p>Following this structure lets team members speak <strong>directly from the checklist</strong> every day, while the Scrum Master simply <strong>updates the table</strong> to handle both documentation and team alignment at once.</p><hr>`,64)])])}const u=t(o,[["render",n]]);export{p as __pageData,u as default};
